#include <bits/stdc++.h>
using namespace std;

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    auto startTime = chrono::steady_clock::now();
    auto elapsed = [&]() -> double {
        return chrono::duration<double>(chrono::steady_clock::now()-startTime).count();
    };

    int N;
    cin >> N;
    vector<double> cx(N), cy(N);
    for(int i=0;i<N;i++) cin >> cx[i] >> cy[i];

    vector<bool> is_prime(N, false);
    {
        vector<bool> sieve(N, true);
        if(N>0) sieve[0]=false;
        if(N>1) sieve[1]=false;
        for(int i=2;(long long)i*i<N;i++)
            if(sieve[i])
                for(int j=i*i;j<N;j+=i) sieve[j]=false;
        for(int i=0;i<N;i++) is_prime[i]=sieve[i];
    }

    auto ddist = [&](int a, int b) -> double {
        double dx=cx[a]-cx[b], dy=cy[a]-cy[b];
        return sqrt(dx*dx+dy*dy);
    };

    auto mult = [&](int s, int src) -> double {
        return (s%10==0 && !is_prime[src]) ? 1.1 : 1.0;
    };

    auto tourCost = [&](const vector<int>& t) -> double {
        double cost=0;
        for(int s=1;s<=N;s++){
            cost += ddist(t[s-1],t[s]) * mult(s, t[s-1]);
        }
        return cost;
    };

    // Build nearest neighbor lists for each city (precompute top-K nearest)
    int K_NN = min(N-1, 15);
    vector<vector<int>> nearNeighbors(N);
    {
        // For efficiency with large N, use grid-based approach
        double minx=1e30,maxx=-1e30,miny=1e30,maxy=-1e30;
        for(int i=0;i<N;i++){
            minx=min(minx,cx[i]); maxx=max(maxx,cx[i]);
            miny=min(miny,cy[i]); maxy=max(maxy,cy[i]);
        }
        int gridSize = max(1, (int)sqrt((double)N / 4.0));
        double cellW = (maxx-minx)/gridSize + 1e-9;
        double cellH = (maxy-miny)/gridSize + 1e-9;
        if(cellW < 1e-12) cellW = 1.0;
        if(cellH < 1e-12) cellH = 1.0;

        vector<vector<int>> grid(gridSize*gridSize);
        auto getCellXY = [&](int id, int &gx, int &gy){
            gx = min(gridSize-1, (int)((cx[id]-minx)/cellW));
            gy = min(gridSize-1, (int)((cy[id]-miny)/cellH));
        };
        for(int i=0;i<N;i++){
            int gx,gy; getCellXY(i,gx,gy);
            grid[gy*gridSize+gx].push_back(i);
        }

        for(int i=0;i<N;i++){
            int gx0,gy0; getCellXY(i,gx0,gy0);
            vector<pair<double,int>> cands;
            for(int rad=0; rad<gridSize*2; rad++){
                for(int dx=-rad;dx<=rad;dx++){
                    for(int dy=-rad;dy<=rad;dy++){
                        if(abs(dx)!=rad && abs(dy)!=rad) continue;
                        int gx=gx0+dx, gy=gy0+dy;
                        if(gx<0||gx>=gridSize||gy<0||gy>=gridSize) continue;
                        for(int id : grid[gy*gridSize+gx]){
                            if(id!=i) cands.push_back({ddist(i,id),id});
                        }
                    }
                }
                if((int)cands.size() >= K_NN*3) break;
            }
            sort(cands.begin(),cands.end());
            nearNeighbors[i].resize(min((int)cands.size(), K_NN));
            for(int j=0;j<(int)nearNeighbors[i].size();j++)
                nearNeighbors[i][j]=cands[j].second;
        }

        // NN tour construction
        vector<int> tour_init(N+1);
        vector<bool> visited(N, false);
        tour_init[0]=0; visited[0]=true;

        for(int step=1;step<N;step++){
            int last=tour_init[step-1];
            int gx0_,gy0_; getCellXY(last,gx0_,gy0_);
            int best=-1; double bestD=1e30;
            for(int rad=0;rad<gridSize*2;rad++){
                if(best!=-1){
                    double minPossible = max(0.0,(double)(rad-1))*min(cellW,cellH);
                    if(minPossible > bestD*1.5) break;
                }
                for(int dx=-rad;dx<=rad;dx++){
                    for(int dy=-rad;dy<=rad;dy++){
                        if(abs(dx)!=rad && abs(dy)!=rad) continue;
                        int gx=gx0_+dx, gy=gy0_+dy;
                        if(gx<0||gx>=gridSize||gy<0||gy>=gridSize) continue;
                        for(int id : grid[gy*gridSize+gx]){
                            if(!visited[id]){
                                double d=ddist(last,id);
                                if(d<bestD){bestD=d;best=id;}
                            }
                        }
                    }
                }
                if(best!=-1 && rad>=1) break;
            }
            tour_init[step]=best;
            visited[best]=true;
        }
        tour_init[N]=0;
        // Store globally
        // We'll just use tour_init below
        // Copy into a global tour
        // Actually let me just define tour here and continue
    }

    // Redo: build tour inline
    vector<int> tour(N+1);
    {
        double minx=1e30,maxx=-1e30,miny=1e30,maxy=-1e30;
        for(int i=0;i<N;i++){
            minx=min(minx,cx[i]); maxx=max(maxx,cx[i]);
            miny=min(miny,cy[i]); maxy=max(maxy,cy[i]);
        }
        int gridSize = max(1, (int)sqrt((double)N / 4.0));
        double cellW = (maxx-minx)/gridSize + 1e-9;
        double cellH = (maxy-miny)/gridSize + 1e-9;
        if(cellW<1e-12) cellW=1.0;
        if(cellH<1e-12) cellH=1.0;

        vector<vector<int>> grid(gridSize*gridSize);
        auto getCellXY = [&](int id, int &gx, int &gy){
            gx=min(gridSize-1,(int)((cx[id]-minx)/cellW));
            gy=min(gridSize-1,(int)((cy[id]-miny)/cellH));
        };
        for(int i=0;i<N;i++){
            int gx,gy; getCellXY(i,gx,gy);
            grid[gy*gridSize+gx].push_back(i);
        }

        vector<bool> visited(N,false);
        tour[0]=0; visited[0]=true;
        {
            int gx,gy; getCellXY(0,gx,gy);
            auto &v=grid[gy*gridSize+gx];
            v.erase(find(v.begin(),v.end(),0));
        }

        for(int step=1;step<N;step++){
            int last=tour[step-1];
            int gx0,gy0; getCellXY(last,gx0,gy0);
            int best=-1; double bestD=1e30;
            for(int rad=0;rad<gridSize*2;rad++){
                if(best!=-1){
                    double minP=max(0.0,(double)(rad-1))*min(cellW,cellH);
                    if(minP>bestD*1.5) break;
                }
                for(int dx=-rad;dx<=rad;dx++){
                    for(int dy=-rad;dy<=rad;dy++){
                        if(abs(dx)!=rad&&abs(dy)!=rad) continue;
                        int gx=gx0+dx,gy=gy0+dy;
                        if(gx<0||gx>=gridSize||gy<0||gy>=gridSize) continue;
                        for(int id:grid[gy*gridSize+gx]){
                            double d=ddist(last,id);
                            if(d<bestD){bestD=d;best=id;}
                        }
                    }
                }
                if(best!=-1&&rad>=1) break;
            }
            tour[step]=best;
            visited[best]=true;
            {
                int gx,gy; getCellXY(best,gx,gy);
                auto &v=grid[gy*gridSize+gx];
                v.erase(find(v.begin(),v.end(),best));
            }
        }
        tour[N]=0;
    }

    double curCost = tourCost(tour);

    vector<int> pos(N);
    auto buildPos = [&](){
        for(int i=0;i<N;i++) pos[tour[i]]=i;
    };
    buildPos();

    // Precompute distances for edges (cache)
    // We'll compute on the fly

    auto edgeCost = [&](int s) -> double {
        // step s (1-indexed), edge from tour[s-1] to tour[s]
        return ddist(tour[s-1],tour[s]) * mult(s, tour[s-1]);
    };

    // Or-opt: remove city at position i, reinsert at position j
    // This changes steps around i and around j
    auto tryRelocate = [&](int i, int j) -> double {
        // Remove tour[i] and insert before position j
        // i is position in tour (1..N-1), j is insertion position
        if(i<1||i>=N) return 0;
        if(j<1||j>N) return 0;
        if(j==i||j==i+1) return 0;

        int city = tour[i];

        // Old cost: edges at steps i, i+1 (involving tour[i])
        // After removal, tour[i-1] connects to tour[i+1] at what was step i
        // But positions shift... this is complex

        // Let's just do it: remove and reinsert, compute new cost for affected region
        // Actually for large N, full recompute is too slow. Let's compute delta.

        // Old edges: (tour[i-1],tour[i]) at step i, (tour[i],tour[i+1]) at step i+1
        // New edge after removal: (tour[i-1],tour[i+1]) but step numbers change for everything after i
        // Step numbers changing means penalty positions change - this makes delta computation very hard

        // For correctness, we need to handle step renumbering. This is expensive.
        // Skip relocate for now, focus on what works.
        return 0;
    };

    // Since step renumbering makes standard TSP moves complex, let's focus on:
    // 1. Swap moves (don't change step numbering)
    // 2. Strategic prime placement at penalty positions

    // Swap: exchange tour[i] and tour[j], positions stay same, step numbers unchanged
    // Affected edges: steps i, i+1, j, j+1 (or fewer if adjacent)

    auto trySwapDelta = [&](int i, int j) -> double {
        if(i==j||i<1||j<1||i>=N||j>=N) return 0;
        if(i>j) swap(i,j);

        double oldC=0, newC=0;

        if(j==i+1){
            // Adjacent: affected steps i, i+1, i+2
            for(int s=i;s<=min(i+2,N);s++) oldC+=edgeCost(s);
            swap(tour[i],tour[j]);
            for(int s=i;s<=min(i+2,N);s++) newC+=edgeCost(s);
            if(newC<oldC-1e-10){
                pos[tour[i]]=i; pos[tour[j]]=j;
                curCost+=newC-oldC;
                return newC-oldC;
            }
            swap(tour[i],tour[j]);
        } else {
            // Non-adjacent: steps i, i+1, j, j+1
            for(int s : {i,i+1,j,j+1}){
                if(s>=1&&s<=N) oldC+=edgeCost(s);
            }
            swap(tour[i],tour[j]);
            for(int s : {i,i+1,j,j+1}){
                if(s>=1&&s<=N) newC+=edgeCost(s);
            }
            if(newC<oldC-1e-10){
                pos[tour[i]]=i; pos[tour[j]]=j;
                curCost+=newC-oldC;
                return newC-oldC;
            }
            swap(tour[i],tour[j]);
        }
        return 0;
    };

    // 2-opt that's aware of penalty: reverse tour[i..j]
    // This changes step assignments, so we need to recompute cost for the whole reversed segment
    auto try2opt = [&](int i, int j) -> double {
        // Reverse tour[i..j], affects steps i to j+1
        if(i<1||j>=N||i>=j) return 0;
        int len = j-i+1;
        if(len > 500) return 0; // limit segment length for speed

        double oldC=0;
        for(int s=i;s<=min(j+1,N);s++) oldC+=edgeCost(s);

        reverse(tour.begin()+i, tour.begin()+j+1);

        double newC=0;
        for(int s=i;s<=min(j+1,N);s++) newC+=edgeCost(s);

        if(newC<oldC-1e-10){
            curCost+=newC-oldC;
            for(int s=i;s<=j;s++) pos[tour[s]]=s;
            return newC-oldC;
        }
        reverse(tour.begin()+i, tour.begin()+j+1);
        return 0;
    };

    // Main optimization loop
    int iter=0;
    double bestCost = curCost;
    vector<int> bestTour = tour;

    while(elapsed() < 4.5){
        bool improved = false;
        iter++;

        // Phase 1: Try placing primes at penalty positions (step 10k, source = tour[10k-1])
        for(int p=9; p<N; p+=10){
            if(is_prime[tour[p]]) continue;
            double bestDelta=0; int bestJ=-1;
            // Search nearby positions for a prime to swap in
            int range = min(500, N);
            for(int delta=-range; delta<=range; delta++){
                int j=p+delta;
                if(j<1||j>=N||j==p) continue;
                if(!is_prime[tour[j]]) continue;
                // Don't steal from another penalty position that already has a prime
                if(j%10==9 && is_prime[tour[j]]) continue;

                // Compute swap delta without actually swapping
                double oldC=0, newC=0;
                int ii=min(p,j), jj=max(p,j);

                if(jj==ii+1){
                    for(int s=ii;s<=min(ii+2,N);s++) oldC+=edgeCost(s);
                    swap(tour[p],tour[j]);
                    for(int s=ii;s<=min(ii+2,N);s++) newC+=edgeCost(s);
                    swap(tour[p],tour[j]);
                } else {
                    for(int s:{ii,ii+1,jj,jj+1}){
                        if(s>=1&&s<=N) oldC+=edgeCost(s);
                    }
                    swap(tour[p],tour[j]);
                    for(int s:{ii,ii+1,jj,jj+1}){
                        if(s>=1&&s<=N) newC+=edgeCost(s);
                    }
                    swap(tour[p],tour[j]);
                }
                double d=newC-oldC;
                if(d<bestDelta){bestDelta=d;bestJ=j;}
            }
            if(bestJ>=0){
                trySwapDelta(p,bestJ);
                improved=true;
            }
        }

        // Phase 2: Swap-based local search using near neighbors
        for(int i=1;i<N&&elapsed()<4.5;i++){
            int ci = tour[i];
            for(int nb : nearNeighbors[ci]){
                int j = pos[nb];
                if(j<1||j>=N||j==i) continue;
                double d = trySwapDelta(i,j);
                if(d < -1e-10) { improved=true; }
            }
            // Also try with neighbors of tour[i-1] and tour[i+1]
            if(i>0){
                int cprev=tour[i-1];
                for(int nb : nearNeighbors[cprev]){
                    int j=pos[nb];
                    if(j<1||j>=N||j==i) continue;
                    double d=trySwapDelta(i,j);
                    if(d<-1e-10) improved=true;
                }
            }
        }

        // Phase 3: 2-opt with near neighbors
        for(int i=1;i<N-1&&elapsed()<4.5;i++){
            int ci=tour[i];
            for(int nb : nearNeighbors[ci]){
                int j=pos[nb];
                if(j<=i||j>=N) continue;
                if(j-i>500) continue;
                double d=try2opt(i,j);
                if(d<-1e-10){improved=true; break;}
            }
        }

        if(curCost < bestCost){
            bestCost = curCost;
            bestTour = tour;
        }

        if(!improved) break;
    }

    // Final: more 2-opt passes if time remains
    while(elapsed() < 4.8){
        bool imp=false;
        for(int i=1;i<N-1&&elapsed()<4.8;i++){
            for(int j=i+1;j<min(i+100,N)&&j<N;j++){
                double d=try2opt(i,j);
                if(d<-1e-10){imp=true;}
            }
        }
        if(!imp) break;
    }

    if(curCost < bestCost){
        bestCost = curCost;
        bestTour = tour;
    }

    cout << N+1 << "\n";
    for(int i=0;i<=N;i++) cout << bestTour[i] << "\n";
}
